import{_ as l,o as i,c as e,a2 as o}from"./chunks/framework.CAKCj7G0.js";const b=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"Linux/README.md","filePath":"Linux/README.md","lastUpdated":1761032501000}'),r={name:"Linux/README.md"};function t(h,a,u,n,d,c){return i(),e("div",null,[...a[0]||(a[0]=[o('<h2 id="进程、线程、协程" tabindex="-1">进程、线程、协程 <a class="header-anchor" href="#进程、线程、协程" aria-label="Permalink to &quot;进程、线程、协程&quot;">​</a></h2><h3 id="进程" tabindex="-1">进程 <a class="header-anchor" href="#进程" aria-label="Permalink to &quot;进程&quot;">​</a></h3><ul><li>有独立的地址空间</li><li>上下文切换开销较大</li><li>并发性效率低</li><li>有程序运行入口</li><li>崩溃后对其它进程不会产生影响</li></ul><h3 id="线程" tabindex="-1">线程 <a class="header-anchor" href="#线程" aria-label="Permalink to &quot;线程&quot;">​</a></h3><ul><li>线程拥有各自的计数器、堆栈、局部变量，共享进程内的资源</li><li>上下文切换开销较小</li><li>并发性效率高</li><li>操作系统调度的最小单元</li><li>不能够独立执行,依存在应用程序,由应用程序提供多个线程执行控制</li><li>崩溃后会影响到整个进程</li><li>线程、协程区别： 线程是操作系统的资源,线程的创建、切换、停止等都非常消耗资源,而创建协程不需要调用操作系统的功能,编程语言自身就能完成,所以协程也被称为用户态线程,协程比线程轻量很多； 线程在多核环境下是能做到真正意义上的并行,而协程是为并发而产生的； 一个具有多个线程的程序可以同时运行几个线程,而协同程序却需要彼此协作的运行； 线程进程都是同步机制,而协程则是异步； 线程是抢占式,而协程是非抢占式的,所以需要用户自己释放使用权来切换到其他协程,因此同一时间其实只有一个协程拥有运行权,相当于单线程的能力； 操作系统对于线程开辟数量限制在千的级别,而协程可以达到上万的级别。</li></ul><h2 id="死锁" tabindex="-1">死锁 <a class="header-anchor" href="#死锁" aria-label="Permalink to &quot;死锁&quot;">​</a></h2><ul><li>争夺共享资源而造成的一种互相等待的现象 （死锁发生，四个必须条件）</li></ul><h3 id="互斥条件" tabindex="-1">互斥条件 <a class="header-anchor" href="#互斥条件" aria-label="Permalink to &quot;互斥条件&quot;">​</a></h3><ul><li>进程对所分配到的资源进行排它性使用,即在一段时间内某资源只由一个进程占用</li></ul><h3 id="请求保持" tabindex="-1">请求保持 <a class="header-anchor" href="#请求保持" aria-label="Permalink to &quot;请求保持&quot;">​</a></h3><ul><li>进程已经保持至少一个资源,但又提出了新的资源请求,而该资源已被其它进程占有,此时请求进程阻塞,但又对自己已获得的其它资源保持不放</li></ul><h3 id="不剥夺" tabindex="-1">不剥夺 <a class="header-anchor" href="#不剥夺" aria-label="Permalink to &quot;不剥夺&quot;">​</a></h3><ul><li>指进程已获得的资源,在未使用完之前,不能被剥夺,只能在使用完时由自己释放</li></ul><h3 id="环路等待" tabindex="-1">环路等待 <a class="header-anchor" href="#环路等待" aria-label="Permalink to &quot;环路等待&quot;">​</a></h3><ul><li>指在发生死锁时,必然存在一个进程——资源的环形链</li></ul><h2 id="进程间通信-ipc" tabindex="-1">进程间通信（IPC） <a class="header-anchor" href="#进程间通信-ipc" aria-label="Permalink to &quot;进程间通信（IPC）&quot;">​</a></h2><h3 id="管道" tabindex="-1">管道 <a class="header-anchor" href="#管道" aria-label="Permalink to &quot;管道&quot;">​</a></h3><ul><li>本质是内核维护的一块内存缓冲区， Linux 系统通过 pipe() 创建管道，生成读写的两个文件描述符（只能应用于有亲缘关系的进程间通信）</li></ul><h3 id="命名管道" tabindex="-1">命名管道 <a class="header-anchor" href="#命名管道" aria-label="Permalink to &quot;命名管道&quot;">​</a></h3><ul><li>为了解决管道仅能亲缘关系进程间通信的问题，提供了一个与路径关联的 FIFO 文件，通过该文件进行数据交互。</li></ul><h3 id="信号-软件中断" tabindex="-1">信号（软件中断） <a class="header-anchor" href="#信号-软件中断" aria-label="Permalink to &quot;信号（软件中断）&quot;">​</a></h3><ul><li>事件发生时对进程的通知机制，是一种异步通信。</li></ul><h3 id="消息队列" tabindex="-1">消息队列 <a class="header-anchor" href="#消息队列" aria-label="Permalink to &quot;消息队列&quot;">​</a></h3><ul><li>消息链表，</li></ul><h3 id="共享内存" tabindex="-1">共享内存 <a class="header-anchor" href="#共享内存" aria-label="Permalink to &quot;共享内存&quot;">​</a></h3><ul><li>多个进程可共享同一块物理内存</li></ul><h3 id="内存映射" tabindex="-1">内存映射 <a class="header-anchor" href="#内存映射" aria-label="Permalink to &quot;内存映射&quot;">​</a></h3><ul><li>磁盘文件的数据映射到内存,用户通过修改内存就能修改磁盘文件</li></ul><h3 id="信号量" tabindex="-1">信号量 <a class="header-anchor" href="#信号量" aria-label="Permalink to &quot;信号量&quot;">​</a></h3><ul><li>主要用来解决进程和线程间并发执行时的同步问题</li><li>信号量的操作分为 P 操作和 V 操作</li><li>P 操作是将信号量的值减 1</li><li>V 操作是将信号量的值加 1。</li><li>当信号量的值小于等于 0 之后,再进行 P 操作时,当前进程或线程会被阻塞,直到另一个进程或线程执行了 V 操作将信号量的值增加到大于 0 之时。</li></ul><h3 id="socket" tabindex="-1">Socket <a class="header-anchor" href="#socket" aria-label="Permalink to &quot;Socket&quot;">​</a></h3><ul><li>网络中不同主机上的应用进程之间进行双向通信的端点的抽象。</li><li>一个套接字就是网络上进程通信的一端,提供了应用层进程利用网络协议交换数据的机制。</li><li>Socket 一般用于网络中不同主机上的进程之间的通信。</li></ul><h2 id="cpu" tabindex="-1">CPU <a class="header-anchor" href="#cpu" aria-label="Permalink to &quot;CPU&quot;">​</a></h2><h3 id="cas" tabindex="-1">CAS <a class="header-anchor" href="#cas" aria-label="Permalink to &quot;CAS&quot;">​</a></h3><ul><li>一种对内存中的共享数据进行操作的一种特殊指令，这个指令会对内存中的共享数据做原子的读写操作。其作用是让CPU比较内存中某个值是否和CPU 中原值相同，如果相同则将这个值更新为新值，不相同则不做更新。</li></ul><h2 id="内存" tabindex="-1">内存 <a class="header-anchor" href="#内存" aria-label="Permalink to &quot;内存&quot;">​</a></h2><h3 id="物理内存" tabindex="-1">物理内存 <a class="header-anchor" href="#物理内存" aria-label="Permalink to &quot;物理内存&quot;">​</a></h3><ul><li>使用物理地址，寻址范围有限</li></ul><h3 id="虚拟内存" tabindex="-1">虚拟内存 <a class="header-anchor" href="#虚拟内存" aria-label="Permalink to &quot;虚拟内存&quot;">​</a></h3><ul><li>为解决物理内存，内存有限，内存碎片化问题而引入的内存管理技术。应用程序与物理内存避免直接交互，应用程序使用的内存由虚拟内存决定</li></ul><h3 id="内存管理" tabindex="-1">内存管理 <a class="header-anchor" href="#内存管理" aria-label="Permalink to &quot;内存管理&quot;">​</a></h3><ul><li>段页式存储管理 将用户程序分为若干段，每段赋予段名 将若干段分成若干页</li><li>为了实现从逻辑地址到物理地址的转化，同时配置了段表和页表</li><li>系统为每一个进程建立一张段表，每个分段有一只页表</li></ul><h2 id="io" tabindex="-1">IO <a class="header-anchor" href="#io" aria-label="Permalink to &quot;IO&quot;">​</a></h2><h3 id="io-模型" tabindex="-1">IO 模型 <a class="header-anchor" href="#io-模型" aria-label="Permalink to &quot;IO 模型&quot;">​</a></h3><h4 id="阻塞-io-bio" tabindex="-1">阻塞 IO（BIO） <a class="header-anchor" href="#阻塞-io-bio" aria-label="Permalink to &quot;阻塞 IO（BIO）&quot;">​</a></h4><ul><li>最常用</li><li>所用文件操作都是阻塞的（socket 操作也是）</li></ul><h4 id="非阻塞-io-nio" tabindex="-1">非阻塞 IO （NIO） <a class="header-anchor" href="#非阻塞-io-nio" aria-label="Permalink to &quot;非阻塞 IO （NIO）&quot;">​</a></h4><h4 id="异步-io-o" tabindex="-1">异步 IO (O) <a class="header-anchor" href="#异步-io-o" aria-label="Permalink to &quot;异步 IO (O)&quot;">​</a></h4><h3 id="io-多路复用" tabindex="-1">IO 多路复用 <a class="header-anchor" href="#io-多路复用" aria-label="Permalink to &quot;IO 多路复用&quot;">​</a></h3><ul><li>把多个 IO 阻塞复用到一个 select or epoll 阻塞上，实现单线程下同时处理多个客户端请求</li><li>优势：系统开销小，不需要创建额外的进程 or 线程，节省了系统资源。</li><li>目前支持多路复用的系统调用：select、pselect、poll、epoll，目前 Linux 使用的 epoll</li></ul><h4 id="epoll" tabindex="-1">epoll <a class="header-anchor" href="#epoll" aria-label="Permalink to &quot;epoll&quot;">​</a></h4><ul><li>支持进程打开的 socket（FD）树不受限制，在高并发场景下能够得到有力的网络支持。</li><li>通过回调的方式得到活跃的 socket，在多数 socket 不活跃的情况下，比 select 效率高出很多。</li><li>通过 mmap（使用同一块内存） 加速内核与用户空间的消息传递</li></ul><h4 id="select" tabindex="-1">select <a class="header-anchor" href="#select" aria-label="Permalink to &quot;select&quot;">​</a></h4><ul><li>支持打开的 socket 有限</li><li>通过线性扫描的方式得到活跃的 socket</li><li>通过复制的方式传到用户空间</li></ul><h3 id="介绍" tabindex="-1">介绍 <a class="header-anchor" href="#介绍" aria-label="Permalink to &quot;介绍&quot;">​</a></h3><ul><li>全称：Unix Domain Sockets 简称 UDS 别名 IPC Socket</li><li>功能：使同一机器上多个进程间相互通信</li></ul><h3 id="与-tcp-ip-通信的区别" tabindex="-1">与 TCP/IP 通信的区别 <a class="header-anchor" href="#与-tcp-ip-通信的区别" aria-label="Permalink to &quot;与 TCP/IP 通信的区别&quot;">​</a></h3><p>维度: UDS TCP/IP socket 标识:</p><ul><li>UDS：一个文件名，例如：/var/lib/example/example.socket</li><li>TCP/IP：IP:Port，例如：192.168.0.2::9090 包处理过程：</li><li>UDS：将应用层数据从一个进程拷贝到另一个进程</li><li>TCP/IP：需要经过网络协议栈，打包拆包、计算校验和、维护序号和应答等 使用场景：</li><li>UDS：同一台机器上两个或多个进程间通信，速度更快</li><li>TCP/IP：跨网络通信</li></ul>',59)])])}const q=l(r,[["render",t]]);export{b as __pageData,q as default};
